{
  "avaliacoes": [
    {
      "id": "Ed615ac401076e86e",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A Resolução ANP nº 817/2020 trata do descomissionamento de instalações de E&P, da devolução de áreas à ANP e da alienação e reversão de bens, reunindo processos antes dispersos em um único instrumento.",
          "trechos": [
            "Ed615ac401076e86e:0:699",
            "Ed615ac401076e86e:699:1397"
          ],
          "condicoes": [
            "Aplicável ao descomissionamento de instalações de exploração e produção de petróleo e gás natural no contexto regulatório brasileiro descrito pela fonte."
          ],
          "limites": [
            "Os trechos não detalham procedimentos específicos de preparação de casco, estanqueidade, estabilidade, lastro, rota, janela meteorológica ou recebimento em estaleiro."
          ]
        },
        {
          "proposicao": "A resolução estabelece requisitos técnicos-ambientais, de segurança operacional e de navegação para o descomissionamento e introduz um PDI único com avaliação comparativa de alternativas.",
          "trechos": [
            "Ed615ac401076e86e:1397:2094"
          ],
          "condicoes": [
            "A avaliação comparativa deve considerar questões técnicas, ambientais, de segurança e econômicas para definir o plano aplicável à instalação."
          ],
          "limites": [
            "A fonte não explicita os critérios detalhados nem a metodologia de ponderação usada na avaliação comparativa.",
            "Não identifica requisitos específicos de certificação para reboque."
          ]
        },
        {
          "proposicao": "Entre os pontos destacados da Resolução ANP nº 817/2020 estão a análise de risco e a apresentação de memorial descritivo do projeto de auxílio à navegação.",
          "trechos": [
            "Ed615ac401076e86e:2094:2424"
          ],
          "condicoes": [
            "O achado decorre do resumo da resolução feito pela fonte, no contexto do PDI e do descomissionamento."
          ],
          "limites": [
            "O trecho está incompleto quanto aos demais documentos exigidos.",
            "A fonte não detalha como esses documentos se relacionam, na prática, à definição de rota, weather window, rebocadores ou recebimento em estaleiro."
          ]
        }
      ]
    },
    {
      "id": "Eaefbc9325a8aea88",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A análise por vários segmentos é apresentada como ferramenta importante para o processo decisório em descomissionamento, e a fonte afirma que essa abordagem já vinha sendo usada de modo satisfatório no Brasil.",
          "trechos": [
            "Eaefbc9325a8aea88:0:698",
            "Eaefbc9325a8aea88:698:1396"
          ],
          "condicoes": [
            "O texto situa essa necessidade no contexto da evolução das práticas de descomissionamento e da crescente complexidade tecnológica."
          ],
          "limites": [
            "A fonte não restringe a ferramenta à decisão sobre reboque para estaleiro; trata do processo decisório de forma ampla.",
            "Não há critérios operacionais específicos para casco, estanqueidade, estabilidade, lastro ou sistemas temporários."
          ]
        },
        {
          "proposicao": "No desmantelamento e na gestão de resíduos, a fonte destaca a possibilidade de formação de uma cadeia logística reversa com reaproveitamento de sucatas ferrosas e reutilização de materiais e equipamentos.",
          "trechos": [
            "Eaefbc9325a8aea88:698:1396",
            "Eaefbc9325a8aea88:1396:2094"
          ],
          "condicoes": [
            "O achado está ligado ao mercado de resíduos de embarcações e à revenda ou reutilização de equipamentos."
          ],
          "limites": [
            "Não demonstra, por si só, viabilidade econômica ou técnica para qualquer FPSO específico.",
            "Não aborda requisitos de recebimento físico da unidade no estaleiro."
          ]
        },
        {
          "proposicao": "A fonte afirma ser possível aproveitar o potencial dos estaleiros brasileiros como instalações certificadas para desmonte e restauração de plataformas, além de mencionar projetos de engenharia para reutilização de estruturas offshore.",
          "trechos": [
            "Eaefbc9325a8aea88:1396:2094"
          ],
          "condicoes": [
            "A proposição é apresentada como possibilidade para fomentar o mercado brasileiro de descomissionamento."
          ],
          "limites": [
            "Trata-se de indicação de potencial e possibilidade, não de inventário de capacidade instalada nem de requisito regulatório.",
            "Não informa critérios de seleção de estaleiro, capacidade de recebimento, interfaces de atracação ou preparação da unidade para entrada no estaleiro."
          ]
        }
      ]
    },
    {
      "id": "E243b5a6abad35913",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte sustenta a necessidade de metodologia com critérios de avaliação para decidir entre remoção ou permanência de instalações, equilibrando proteção ambiental, risco operacional e viabilidade técnica e econômica.",
          "trechos": [
            "E243b5a6abad35913:0:692",
            "E243b5a6abad35913:692:1392"
          ],
          "condicoes": [
            "A necessidade é apresentada porque os regulamentos no país estariam dispersos e careceriam de aperfeiçoamento, segundo a própria fonte."
          ],
          "limites": [
            "O trecho trata da decisão de alternativas de descomissionamento em nível geral.",
            "Não traz parâmetros objetivos para navegabilidade, reboque, integridade do casco ou janela meteorológica."
          ]
        },
        {
          "proposicao": "A avaliação comparativa multicritério é descrita como metodologia semi-quantitativa, multidisciplinar, com possibilidade de ajuste de critérios e pesos conforme o cenário e com participação de stakeholders na definição e validação.",
          "trechos": [
            "E243b5a6abad35913:692:1392"
          ],
          "condicoes": [
            "Os critérios e pesos podem ser reavaliados e ajustados em função do cenário ambiental, legal e de outras condições mencionadas pela fonte."
          ],
          "limites": [
            "A fonte apresenta características metodológicas, não resultados empíricos de sua aplicação a um caso de FPSO.",
            "Não define pesos, fórmulas ou critérios mínimos universais."
          ]
        },
        {
          "proposicao": "Como benchmark estrangeiro, a fonte registra que orientações do Reino Unido usam cinco critérios principais na avaliação comparativa: segurança, meio ambiente, técnica, social e econômica.",
          "trechos": [
            "E243b5a6abad35913:1392:2091",
            "E243b5a6abad35913:2091:2468"
          ],
          "condicoes": [
            "O achado refere-se a orientação estrangeira citada como referência metodológica."
          ],
          "limites": [
            "Não deve ser convertido em requisito brasileiro.",
            "A fonte não demonstra adaptação formal desses critérios para o recorte específico de preparação para reboque e estaleiro."
          ]
        }
      ]
    },
    {
      "id": "Ea39e9a92f4068189",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve componentes de estruturas offshore e menciona que, no descomissionamento do topside, deve-se observar o destino dos equipamentos de processamento e da estrutura do convés.",
          "trechos": [
            "Ea39e9a92f4068189:692:1385"
          ],
          "condicoes": [
            "Inserido em descrição geral de componentes e etapas de descomissionamento."
          ],
          "limites": [
            "Não trata de casco, estanqueidade, estabilidade, lastro, sistemas temporários, certificação para reboque, rota, janela ou recebimento em estaleiro."
          ]
        }
      ]
    },
    {
      "id": "E824e160f24ddc5f9",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte define descomissionamento de instalações offshore como conjunto de atividades ao final da vida produtiva do campo e menciona abandono de poços, remoção, desmantelamento e possível reutilização da estrutura.",
          "trechos": [
            "E824e160f24ddc5f9:0:700"
          ],
          "condicoes": [
            "Definição geral introdutória sobre descomissionamento offshore."
          ],
          "limites": [
            "Não detalha requisitos técnicos ou operacionais do recorte de preparação para reboque e estaleiro."
          ]
        },
        {
          "proposicao": "A fonte informa que previsões de data e custos de descomissionamento devem constar no Plano de Desenvolvimento do campo e que estimativas de custo variam entre operadoras por fatores como experiência, profundidade, período e risco.",
          "trechos": [
            "E824e160f24ddc5f9:0:700",
            "E824e160f24ddc5f9:700:1398"
          ],
          "condicoes": [
            "Apresentado em contexto econômico e de planejamento geral."
          ],
          "limites": [
            "Não fornece critérios de seleção de estaleiro, rota, certificação, estanqueidade ou estabilidade para tow-out."
          ]
        }
      ]
    }
  ],
  "concluir": false,
